     * This is a cascade delete for the node and all nodes depending on it.
     * @param node Node to remove.
     */
    void closeNode(const NodePtr &node) {
        if (!node) return;

        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
        NodeSet closedNodes;
