    void closeNodeInternal(const NodePtr &node) {
        if (!node) return;

        // Clean up dependent relationships - this node observes others
        if (m_dependentList.contains(node)) {
            for (auto dep : m_dependentList[node]) {
                if (auto locked_dep = dep.lock()) {
